package run.ikaros.document; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/documents") public class DocumentCommentController{private final DocumentCommentService service;public DocumentCommentController(DocumentCommentService s){service=s;}@PostMapping("/{documentId}/comments")public Mono<DocumentCommentView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID documentId,@Valid@RequestBody CreateDocumentCommentRequest r){return service.create(o,documentId,r);}@GetMapping("/{documentId}/comments")public Flux<DocumentCommentView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID documentId){return service.list(o,documentId);}@PostMapping("/comments/{commentId}/actions/resolve")public Mono<DocumentCommentView> resolve(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID commentId){return service.resolve(o,commentId);}@DeleteMapping("/comments/{commentId}")public Mono<Void> delete(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID commentId){return service.delete(o,commentId);}}
